/* Ivory Digital Phase 5.4 — Complete Studio Workspace & Communications. */
function relativeTime(value){const seconds=Math.round((new Date(value)-new Date())/1000),abs=Math.abs(seconds);if(abs<60)return'just now';if(abs<3600)return`${Math.round(abs/60)} min${Math.round(abs/60)===1?'':'s'} ${seconds<0?'ago':'from now'}`;if(abs<86400)return`${Math.round(abs/3600)} hour${Math.round(abs/3600)===1?'':'s'} ${seconds<0?'ago':'from now'}`;return`${Math.round(abs/86400)} day${Math.round(abs/86400)===1?'':'s'} ${seconds<0?'ago':'from now'}`}
function prettyAction(value=''){return value.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
function bytes(value=0){if(value<1024)return`${value} B`;if(value<1048576)return`${(value/1024).toFixed(1)} KB`;return`${(value/1048576).toFixed(1)} MB`}
async function apiUpload(path,formData,method='POST'){const response=await fetch(path,{method,body:formData,headers:{'X-CSRF-Token':csrf()},credentials:'same-origin'});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.detail||'Something went wrong. Please try again.');return body}
function openWorkDialog(title,kicker,body,onSubmit,submitLabel='Save'){const dialog=$('#work-dialog');dialog.innerHTML=`<form id="work-form"><header><div><span class="eyebrow">${escapeHtml(kicker)}</span><h2>${escapeHtml(title)}</h2></div><button type="button" class="close-work" aria-label="Close">×</button></header>${body}<p id="work-error" class="error"></p><footer><button type="button" class="button quiet close-work">Cancel</button><button class="button primary" type="submit">${escapeHtml(submitLabel)}</button></footer></form>`;dialog.querySelectorAll('.close-work').forEach(button=>button.onclick=()=>dialog.close());dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const submit=event.submitter;submit.disabled=true;try{await onSubmit(dialog,event);dialog.close()}catch(error){dialog.querySelector('#work-error').textContent=error.message;submit.disabled=false}};dialog.showModal();return dialog}

async function updateUnreadCount(){try{const rows=await api('/api/studio/emails?unread_only=true');$('#unread-count').textContent=rows.length||''}catch{$('#unread-count').textContent=''}}
function attentionSection(title,rows,renderer){const key=title.toLowerCase().replaceAll(' ','-');return rows.length?`<article class="panel attention-list" data-attention="${escapeAttr(key)}"><header><h3>${escapeHtml(title)}</h3><span>${rows.length}</span></header>${rows.map(renderer).join('')}</article>`:''}
async function loadToday(){if(!$('#today-board'))return;try{todayData=await api('/api/studio/today');const c=todayData.counts;$('#today-metrics').innerHTML=`<button data-today-route="enquiries"><strong>${c.new_enquiries}</strong><span>New enquiries</span></button><button data-today-route="communications" data-comms="review"><strong>${c.review}</strong><span>Awaiting review</span></button><button data-today-route="communications" data-comms="inbox"><strong>${c.updates}</strong><span>Client updates</span></button><button data-today-route="payments"><strong>${c.payments}</strong><span>Payments due</span></button><button data-today-route="communications" data-comms="review"><strong>${c.failed}</strong><span>Needs fixing</span></button><button data-today-tasks><strong>${c.tasks}</strong><span>Open tasks</span></button>`;$('#today-board').innerHTML=[attentionSection('New enquiries',todayData.enquiries,row=>`<button data-today-enquiry="${row.id}"><span class="attention-icon">♡</span><div><strong>${escapeHtml(row.names)}</strong><small>${escapeHtml(row.event_date?formatDate(row.event_date):'Date not supplied')} · ${escapeHtml(row.venue||'Venue not supplied')}</small></div><em>${relativeTime(row.created_at)}</em></button>`),attentionSection('Review and workflow',todayData.actions,row=>`<button data-today-action="${row.id}"><span class="attention-icon ${row.status}">${row.status==='error'?'!':'✉'}</span><div><strong>${escapeHtml(row.payload.name||row.payload.task_title||'Workflow item')}</strong><small>${escapeHtml(row.booking_name)} · ${escapeHtml(prettyAction(row.status))}</small></div><em>${relativeTime(row.due_at)}</em></button>`),attentionSection('Tasks',todayData.tasks,row=>`<button data-today-booking="${row.booking_id||''}"><span class="attention-icon">✓</span><div><strong>${escapeHtml(row.title)}</strong><small>${escapeHtml(row.booking_name)}${row.due_date?' · due '+formatDate(row.due_date):''}</small></div><em>${row.due_date&&row.due_date<new Date().toISOString().slice(0,10)?'Overdue':'Open'}</em></button>`),attentionSection('Payments due',todayData.payments,row=>`<button data-today-booking="${row.booking_id}"><span class="attention-icon ${row.overdue?'error':''}">£</span><div><strong>${escapeHtml(row.booking_name)} · ${escapeHtml(row.number)}</strong><small>${money(row.outstanding_pence)} outstanding · due ${formatDate(row.due_date)}</small></div><em>${row.overdue?'Overdue':'Upcoming'}</em></button>`),attentionSection('Recent client updates',todayData.notifications,row=>`<button data-notification="${row.id}" data-today-booking="${row.booking_id||''}"><span class="attention-icon">●</span><div><strong>${escapeHtml(row.title)}</strong><small>${escapeHtml(row.body)}</small></div><em>${relativeTime(row.created_at)}</em></button>`),attentionSection('Next 60 days',todayData.upcoming,row=>`<button data-today-booking="${row.id}"><span class="attention-icon">◇</span><div><strong>${escapeHtml(row.title)}</strong><small>${formatDate(row.event_date)} · ${escapeHtml(row.venue||'Venue TBC')}</small></div><em>${escapeHtml(statusLabel(row.status))}</em></button>`)].join('')||empty('You are all caught up','Nothing needs your attention right now.');document.querySelectorAll('[data-today-route]').forEach(button=>button.onclick=()=>{if(button.dataset.comms)communicationsTab=button.dataset.comms;showSection(button.dataset.todayRoute)});document.querySelector('[data-today-tasks]')?.addEventListener('click',()=>document.querySelector('[data-attention="tasks"]')?.scrollIntoView({behavior:'smooth',block:'center'}));document.querySelectorAll('[data-today-enquiry]').forEach(button=>button.onclick=async()=>{const id=button.dataset.todayEnquiry;await showSection('enquiries');await openEnquiryWorkspaceV56(id)});document.querySelectorAll('[data-today-action]').forEach(button=>button.onclick=()=>{communicationsTab='review';showSection('communications')});document.querySelectorAll('[data-today-booking]').forEach(button=>button.onclick=async()=>{if(button.dataset.notification)await api(`/api/studio/notifications/${button.dataset.notification}/read`,{method:'POST'});if(button.dataset.todayBooking){await showSection('weddings');await openJourneyV54(button.dataset.todayBooking)}else await loadToday()})}catch(error){$('#today-board').innerHTML=empty('Today could not be loaded',error.message)}}

var v54SearchTimer;
$('#global-search').addEventListener('input',event=>{clearTimeout(v54SearchTimer);const value=event.target.value.trim(),results=$('#search-results');if(value.length<2){results.classList.add('hidden');return}v54SearchTimer=setTimeout(async()=>{try{const data=await api(`/api/studio/search?q=${encodeURIComponent(value)}`);results.innerHTML=data.results.length?data.results.map(row=>`<button data-search-type="${row.type}" data-search-id="${row.id}"><strong>${escapeHtml(row.title)}</strong><small>${escapeHtml(row.subtitle)}</small></button>`).join(''):'<p>No matching couples, enquiries or invoices.</p>';results.classList.remove('hidden');results.querySelectorAll('[data-search-id]').forEach(button=>button.onclick=async()=>{results.classList.add('hidden');$('#global-search').value='';if(button.dataset.searchType==='booking'){await showSection('weddings');await openJourneyV54(button.dataset.searchId)}else{await showSection('enquiries');await openEnquiryWorkspaceV56(button.dataset.searchId)}})}catch{results.classList.add('hidden')}},220)});document.addEventListener('click',event=>{if(!event.target.closest('.global-search'))$('#search-results').classList.add('hidden')});

const enquiryStatusLabels={new:'New',contacted:'Contacted',quote_draft:'Quote draft',quote_sent:'Quote sent',quote_viewed:'Quote viewed',quote_expired:'Quote expired',closed:'Closed',booked:'Booked'};
var enquiryRowsV56=[];
window.activeEnquiryId=null;
function enquiryStage(row){return enquiryStatusLabels[row.status]||prettyAction(row.status||'new')}
async function loadEnquiriesV54(){try{enquiryRowsV56=await api('/api/studio/enquiries');window.activeEnquiryId=null;$('#enquiry-workspace').classList.add('hidden');$('#enquiry-list').classList.remove('hidden');const rows=enquiryRowsV56;$('#enquiry-list').innerHTML=rows.length?rows.map(row=>`<article class="panel enquiry-card ${row.status==='closed'?'closed-record':''}"><div class="enquiry-avatar">${escapeHtml(initials([row.first_name,row.partner_name].filter(Boolean).join(' & ')))}</div><div class="enquiry-main"><span>${row.event_date?formatDate(row.event_date):'Date not supplied'}</span><h2>${escapeHtml(row.first_name)}${row.partner_name?' & '+escapeHtml(row.partner_name):''}</h2><p>${escapeHtml(row.venue||'Venue not supplied')} ${row.package_interest?'· '+escapeHtml(row.package_interest):''}</p><small>${escapeHtml(row.email)}${row.phone?' · '+escapeHtml(row.phone):''}</small>${row.message?`<blockquote>${escapeHtml(row.message)}</blockquote>`:''}${row.answers?.length?`<details><summary>View all answers</summary><dl class="enquiry-answers">${row.answers.map(item=>`<div><dt>${escapeHtml(item.label)}</dt><dd>${escapeHtml(item.answer)}</dd></div>`).join('')}</dl></details>`:''}<div class="card-actions">${row.status==='booked'?`<button class="button quiet open-booked-wedding" data-booking="${row.booking_id||''}">Open wedding</button>`:row.status==='closed'?`<button class="button quiet reopen-enquiry" data-enquiry="${row.id}">Reopen enquiry</button>`:`<button class="button primary open-enquiry" data-enquiry="${row.id}">${row.quote_status?'Open enquiry':'Prepare quote'}</button><button class="button quiet close-enquiry" data-enquiry="${row.id}">Close enquiry</button>`}</div></div><em>${escapeHtml(enquiryStage(row))}</em></article>`).join(''):empty('No enquiries yet','Publish your enquiry form when it is ready. New submissions will appear here automatically.');document.querySelectorAll('.open-enquiry').forEach(button=>button.onclick=()=>openEnquiryWorkspaceV56(button.dataset.enquiry));document.querySelectorAll('.open-booked-wedding').forEach(button=>button.onclick=async()=>{if(!button.dataset.booking)return;await showSection('weddings');await openJourneyV54(button.dataset.booking)});document.querySelectorAll('.close-enquiry').forEach(button=>button.onclick=()=>openCloseEnquiry(button.dataset.enquiry));document.querySelectorAll('.reopen-enquiry').forEach(button=>button.onclick=async()=>{await api(`/api/studio/enquiries/${button.dataset.enquiry}/reopen`,{method:'POST'});await loadEnquiriesV54();toast('Enquiry reopened.')})}catch(error){toast(error.message,true)}}
function enquiryWorkspaceView(row,j){const sent=j.quote?.status==='sent',viewed=!!j.quote?.viewed_at;return `<button id="back-enquiries" class="text-button">← All enquiries</button><header class="journey-hero panel enquiry-hero"><div><span class="eyebrow">${escapeHtml(enquiryStage(row))}</span><h1>${escapeHtml(j.title)}</h1><p>${escapeHtml(formatDate(j.event_date))} · ${escapeHtml(j.venue||'Venue to be confirmed')}</p></div><div class="journey-hero-actions"><button id="mark-enquiry-booked" class="button quiet">Mark as booked</button><button id="close-open-enquiry" class="button quiet">Close enquiry</button></div></header><div class="enquiry-workspace-grid"><section>${quoteBuilder(j)}${j.emails?.length?`<article class="panel workspace-card"><header><div><span class="eyebrow">EMAIL HISTORY</span><h2>Messages with this couple</h2></div></header><div class="message-thread">${j.emails.map(emailMessageCard).join('')}</div></article>`:''}</section><aside><article class="panel side-card"><span class="eyebrow">ENQUIRY DETAILS</span><h3>${escapeHtml(j.title)}</h3><p>${escapeHtml(row.email)}<br>${escapeHtml(row.phone||'No telephone number')}</p>${row.package_interest?`<p><strong>Interested in:</strong><br>${escapeHtml(row.package_interest)}</p>`:''}${row.message?`<blockquote>${escapeHtml(row.message)}</blockquote>`:''}${row.answers?.length?`<details><summary>All answers</summary><dl class="enquiry-answers">${row.answers.map(item=>`<div><dt>${escapeHtml(item.label)}</dt><dd>${escapeHtml(item.answer)}</dd></div>`).join('')}</dl></details>`:''}</article><article class="panel side-card"><span class="eyebrow">QUOTE PROGRESS</span><h3>${viewed?'Viewed by couple':sent?'Sent — awaiting choice':j.quote?.status==='draft'?'Draft saved':'Not started'}</h3><p>${viewed?`First viewed ${new Date(j.quote.viewed_at).toLocaleString('en-GB')}`:sent?'The enquiry stays here until they accept.':'Saving a draft never sends an email.'}</p></article></aside></div>`}
async function openEnquiryWorkspaceV56(id){try{const row=enquiryRowsV56.find(item=>item.id===id)||((await api('/api/studio/enquiries')).find(item=>item.id===id));if(!row)throw new Error('Enquiry not found');window.activeEnquiryId=id;activeJourney=await api(`/api/studio/enquiries/${id}/workspace`,{method:'POST',body:JSON.stringify({title:''})});if(!packages.length)await loadPackages();quoteTemplates=await api('/api/studio/quote-templates');$('#enquiry-list').classList.add('hidden');const workspace=$('#enquiry-workspace');workspace.classList.remove('hidden');workspace.innerHTML=enquiryWorkspaceView(row,activeJourney);mountQuoteTemplatePicker(activeJourney);$('#back-enquiries').onclick=loadEnquiriesV54;$('#close-open-enquiry').onclick=()=>openCloseEnquiry(id);$('#mark-enquiry-booked').onclick=()=>markEnquiryBookedV56(id);wireClientJourneyControls()}catch(error){toast(error.message,true)}}
window.openEnquiryWorkspaceV56=openEnquiryWorkspaceV56;
async function markEnquiryBookedV56(id){if(!confirm('Move this enquiry into Weddings now? Use this only when the booking has been agreed outside the quote acceptance flow.'))return;try{const journey=await api(`/api/studio/enquiries/${id}/mark-booked`,{method:'POST',body:JSON.stringify({title:''})});dashboard=await api('/api/studio/dashboard');render();await showSection('weddings');await openJourneyV54(journey.id);toast('The enquiry is now a wedding.')}catch(error){toast(error.message,true)}}
async function refreshEnquiriesQuietlyV56(){if(currentSection!=='enquiries'||window.activeEnquiryId||document.querySelector('dialog[open]'))return;const before=new Set(enquiryRowsV56.map(item=>item.id));await loadEnquiriesV54();const added=enquiryRowsV56.filter(item=>!before.has(item.id)&&item.status==='new');if(added.length)toast(`${added.length} new enquir${added.length===1?'y':'ies'} received.`)}
setInterval(refreshEnquiriesQuietlyV56,20000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshEnquiriesQuietlyV56()});
window.addEventListener('focus',refreshEnquiriesQuietlyV56);
function openCloseEnquiry(id){const body=`<div class="form-grid"><label>Outcome<select id="close-outcome"><option value="no_reply">No reply</option><option value="not_available">Date not available</option><option value="chose_someone_else">Chose another supplier</option><option value="budget">Budget</option><option value="duplicate">Duplicate</option><option value="other">Other</option></select></label><label class="wide-field">Private note<textarea id="close-note" rows="3"></textarea></label></div>`;openWorkDialog('Close this enquiry','ENQUIRY OUTCOME',body,async dialog=>{await api(`/api/studio/enquiries/${id}/close`,{method:'POST',body:JSON.stringify({outcome:dialog.querySelector('#close-outcome').value,note:dialog.querySelector('#close-note').value})});await loadEnquiriesV54();toast('Enquiry closed and kept in the history.')},'Close enquiry')}

async function loadWeddingsV54(){try{weddings=await api('/api/studio/bookings');$('#journey-workspace').classList.add('hidden');$('#wedding-list').classList.remove('hidden');renderWeddingList(weddings)}catch(error){toast(error.message,true)}}
function renderWeddingList(rows){const active=rows.filter(row=>row.status!=='archived'),archived=rows.filter(row=>row.status==='archived');$('#wedding-list').innerHTML=`<div class="record-toolbar"><label>⌕<input id="wedding-filter" placeholder="Filter couples, venue or date"></label><span>${active.length} active wedding${active.length===1?'':'s'}</span></div><div id="wedding-cards">${weddingCards(active)}${archived.length?`<details class="archived-list"><summary>${archived.length} archived wedding${archived.length===1?'':'s'}</summary>${weddingCards(archived)}</details>`:''}</div>`;$('#wedding-filter').oninput=event=>{const q=event.target.value.toLowerCase();document.querySelectorAll('.wedding-card').forEach(card=>card.classList.toggle('hidden',!card.dataset.search.includes(q)))};document.querySelectorAll('[data-wedding]').forEach(button=>button.onclick=()=>openJourneyV54(button.dataset.wedding))}
function weddingCards(rows){return rows.length?rows.map(row=>`<button class="panel wedding-card" data-wedding="${row.id}" data-search="${escapeAttr(`${row.title} ${row.venue||''} ${row.event_date||''}`.toLowerCase())}"><span class="wedding-date"><b>${row.event_date?new Date(row.event_date+'T12:00:00').getDate():'—'}</b><small>${row.event_date?new Intl.DateTimeFormat('en-GB',{month:'short'}).format(new Date(row.event_date+'T12:00:00')):'TBC'}</small></span><div><span>${escapeHtml(formatDate(row.event_date))}</span><h2>${escapeHtml(row.title)}</h2><p>${escapeHtml(row.venue||'Venue to be confirmed')}</p></div><em class="journey-chip">${escapeHtml(statusLabel(row.status))}</em><i>›</i></button>`).join(''):empty('No weddings yet','A couple appears here after accepting their quote or when you deliberately mark the enquiry as booked.')}

const journeyTabs=[['overview','Overview'],['journey','Client journey'],['emails','Emails'],['payments','Payments'],['files','Files'],['activity','Notes & activity']];
function journeyHeader(j){return `<button id="back-weddings" class="text-button">← All weddings</button><header class="journey-hero panel"><div><span class="eyebrow">${escapeHtml(statusLabel(j.status))}</span><h1>${escapeHtml(j.title)}</h1><p>${escapeHtml(formatDate(j.event_date))} · ${escapeHtml(j.venue||'Venue to be confirmed')}</p></div><div class="journey-hero-actions"><button id="edit-booking" class="button quiet">Edit details</button><button id="move-booking" class="button quiet">Move date</button><button id="copy-portal" class="button quiet">Copy couple link</button>${!['completed','cancelled','archived'].includes(j.status)?'<button id="complete-wedding" class="button primary">Wedding complete</button><button id="cancel-wedding" class="button danger">Cancel</button>':j.status==='archived'?'<button id="restore-wedding" class="button quiet">Restore</button>':'<button id="archive-wedding" class="button quiet">Archive</button>'}</div></header><nav class="journey-tabs" aria-label="Wedding workspace">${journeyTabs.map(([key,label])=>`<button data-journey-tab="${key}" class="${activeJourneyTab===key?'active':''}">${label}${key==='emails'&&j.emails.some(item=>!item.is_read)?'<i></i>':''}</button>`).join('')}</nav><section id="journey-tab-content"></section>`}

async function openJourneyV54(id,tab){try{const changed=activeJourney?.id!==id;activeJourney=await api(`/api/studio/bookings/${id}/journey`);if(changed&&!tab)activeJourneyTab='overview';if(tab)activeJourneyTab=tab;if(!packages.length)await loadPackages();if(!workflows.length)workflows=await api('/api/studio/workflows');$('#wedding-list').classList.add('hidden');const workspace=$('#journey-workspace');workspace.classList.remove('hidden');workspace.innerHTML=journeyHeader(activeJourney);renderJourneyTab();wireJourneyShell()}catch(error){toast(error.message,true)}}
async function openJourney(id){return openJourneyV54(id)}

function journeySummary(j){const invoice=j.invoices.find(item=>item.status!=='void'),openTasks=j.tasks.filter(item=>item.status!=='completed');return `<div class="journey-summary"><article><span>Wedding date</span><strong>${escapeHtml(formatDate(j.event_date))}</strong><small>${escapeHtml(j.venue||'Venue TBC')}</small></article><article><span>Client stage</span><strong>${escapeHtml(statusLabel(j.status))}</strong><small>${j.accepted_quote?.accepted_at?'Quote accepted':'Quote in progress'}</small></article><article><span>Balance</span><strong>${invoice?money(invoice.outstanding_pence):'No invoice'}</strong><small>${invoice?.due_date?'Due '+formatDate(invoice.due_date):'Created when a quote is accepted'}</small></article><article><span>Open tasks</span><strong>${openTasks.length}</strong><small>${openTasks[0]?.due_date?'Next due '+formatDate(openTasks[0].due_date):'Nothing urgent'}</small></article></div>`}
function quickNotes(j){return `<article class="panel workspace-card"><header><div><span class="eyebrow">PRIVATE NOTES</span><h2>Things to remember</h2></div><button id="add-note" class="button quiet">＋ Note</button></header><div class="workspace-list">${j.notes.length?j.notes.slice(0,5).map(row=>`<div><span class="list-mark">✎</span><div><p>${escapeHtml(row.body)}</p><small>${new Date(row.created_at).toLocaleString('en-GB')}</small></div><button data-delete-note="${row.id}" aria-label="Delete note">×</button></div>`).join(''):empty('No private notes','Add anything you want to remember about this wedding.')}</div></article>`}
function quickTasks(j){return `<article class="panel workspace-card"><header><div><span class="eyebrow">TASKS</span><h2>Your next actions</h2></div><button id="add-task" class="button quiet">＋ Task</button></header><div class="workspace-list">${j.tasks.length?j.tasks.map(row=>`<div class="${row.status==='completed'?'done':''}"><button class="task-check" data-toggle-task="${row.id}" data-task-status="${row.status}" aria-label="${row.status==='completed'?'Reopen':'Complete'} task">${row.status==='completed'?'✓':'○'}</button><div><p>${escapeHtml(row.title)}</p><small>${row.due_date?'Due '+formatDate(row.due_date):'No due date'}${row.notes?' · '+escapeHtml(row.notes):''}</small></div><button data-delete-task="${row.id}" aria-label="Delete task">×</button></div>`).join(''):empty('No tasks','Add a private reminder for yourself.')}</div></article>`}
function overviewTab(j){return `${journeySummary(j)}<div class="overview-grid"><section>${quickTasks(j)}${quickNotes(j)}</section><aside>${couplePanel(j)}${calendarPanel(j)}${workflowPanel(j)}</aside></div>`}
function clientJourneyTab(j){const invoice=j.invoices.find(item=>item.status!=='void'),accepted=!!j.accepted_quote?.accepted_at;return `<div class="journey-grid"><section class="journey-main">${accepted?acceptedQuotePanel(j):quoteBuilder(j)}${invoice?invoicePanel(invoice):''}${contractPanel(j)}${submittedFormsPanel(j)}</section><aside class="journey-side">${couplePanel(j)}${workflowPanel(j)}${calendarPanel(j)}</aside></div>`}
function emailsTab(j){return `<article class="panel workspace-card email-workspace"><header><div><span class="eyebrow">CONVERSATION</span><h2>Emails with ${escapeHtml(j.title)}</h2><p>Messages sent through Studio and matched replies stay together.</p></div><button id="compose-booking-email" class="button primary">＋ Write email</button></header>${j.emails.length?`<div class="message-thread">${j.emails.map(emailMessageCard).join('')}</div>`:empty('No emails here yet','Write a personal message or refresh the Communications inbox to bring replies in.')}</article>`}
function emailMessageCard(row){return `<article class="message-card ${row.direction} ${row.is_read?'':'unread'}" data-email-message="${row.id}"><div class="message-direction">${row.direction==='inbound'?'↙':'↗'}</div><div><header><strong>${escapeHtml(row.subject||'(No subject)')}</strong><span>${new Date(row.sent_at).toLocaleString('en-GB')}</span></header><small>${row.direction==='inbound'?'From '+escapeHtml(row.sender):'To '+escapeHtml(row.recipient)}</small><p>${escapeHtml(row.body_text||'')}</p>${row.attachments?.length?`<footer>${row.attachments.map((item,index)=>`<a href="/api/studio/emails/${row.id}/attachments/${index}">📎 ${escapeHtml(item.name)}</a>`).join('')}</footer>`:''}${row.direction==='inbound'?`<button class="text-action reply-email" data-message="${row.id}">Reply</button>`:''}</div></article>`}
function paymentsTab(j){return `<div class="payment-workspace">${j.invoices.length?j.invoices.map(invoicePanel).join(''):empty('No invoice yet','The itemised invoice is created automatically when this couple accepts their quote.')}</div>`}
function filesTab(j){return `<article class="panel workspace-card"><header><div><span class="eyebrow">FILES</span><h2>Documents for this wedding</h2><p>Keep supplier notes, plans and useful paperwork beside the couple.</p></div><button id="upload-document" class="button primary">＋ Upload file</button></header><div class="file-list">${j.documents.length?j.documents.map(row=>`<div><span class="file-icon">${row.content_type.includes('pdf')?'PDF':'FILE'}</span><div><strong>${escapeHtml(row.name)}</strong><small>${bytes(row.size_bytes)} · ${new Date(row.created_at).toLocaleDateString('en-GB')}${row.description?' · '+escapeHtml(row.description):''}</small></div><a href="${row.download_url}">Download</a><button data-delete-document="${row.id}">Remove</button></div>`).join(''):empty('No files uploaded','Add a PDF, image, Word or Excel document when you need it.')}</div></article>`}
function activityTab(j){return `<div class="overview-grid"><section>${quickNotes(j)}${quickTasks(j)}</section><aside><article class="panel workspace-card"><header><div><span class="eyebrow">ACTIVITY</span><h2>Permanent history</h2></div></header><div class="activity-list">${j.activity.length?j.activity.map(row=>`<div><span></span><div><strong>${escapeHtml(prettyAction(row.action))}</strong><small>${new Date(row.created_at).toLocaleString('en-GB')}</small></div></div>`).join(''):empty('No activity yet','Important changes will appear here.')}</div></article></aside></div>`}

function renderJourneyTab(){if(!activeJourney)return;document.querySelectorAll('[data-journey-tab]').forEach(button=>button.classList.toggle('active',button.dataset.journeyTab===activeJourneyTab));const renderers={overview:overviewTab,journey:clientJourneyTab,emails:emailsTab,payments:paymentsTab,files:filesTab,activity:activityTab};$('#journey-tab-content').innerHTML=(renderers[activeJourneyTab]||overviewTab)(activeJourney);wireJourneyTab()}
function wireJourneyShell(){$('#back-weddings').onclick=()=>loadWeddingsV54();document.querySelectorAll('[data-journey-tab]').forEach(button=>button.onclick=()=>{activeJourneyTab=button.dataset.journeyTab;renderJourneyTab()});$('#copy-portal').onclick=async()=>{await navigator.clipboard.writeText(activeJourney.portal_url);toast('Secure couple link copied.')};$('#edit-booking').onclick=openEditBooking;$('#move-booking').onclick=openMoveBooking;$('#complete-wedding')?.addEventListener('click',async()=>{await api(`/api/studio/bookings/${activeJourney.id}/complete`,{method:'POST',body:JSON.stringify({completed:true})});await openJourneyV54(activeJourney.id);toast('Wedding completed. Its full history is still here.')});$('#cancel-wedding')?.addEventListener('click',cancelWedding);$('#archive-wedding')?.addEventListener('click',async()=>{await api(`/api/studio/bookings/${activeJourney.id}/archive`,{method:'POST'});await loadWeddingsV54();toast('Wedding moved into the archive.')});$('#restore-wedding')?.addEventListener('click',async()=>{await api(`/api/studio/bookings/${activeJourney.id}/restore`,{method:'POST'});await openJourneyV54(activeJourney.id);toast('Wedding restored.')})}
function wireClientJourneyControls(){$('#save-quote')?.addEventListener('click',()=>saveJourneyQuote(false));$('#review-quote-email')?.addEventListener('click',()=>saveJourneyQuote(true));$('#apply-quote-template')?.addEventListener('click',applySelectedQuoteTemplate);$('#open-quote-templates')?.addEventListener('click',()=>showSection('quote-templates'));$('#add-custom-quote-item')?.addEventListener('click',()=>{$('#quote-custom-items').insertAdjacentHTML('beforeend',quoteCustomItemRow());wireQuoteCustomRows()});wireQuoteAddonModes();wireQuoteCustomRows();$('#amend-quote')?.addEventListener('click',amendQuote);document.querySelectorAll('.record-payment').forEach(button=>button.onclick=()=>openPayment(button.dataset.invoice,Number(button.dataset.outstanding)));$('#issue-contract')?.addEventListener('click',issueContract);$('#special-arrangement')?.addEventListener('click',setSpecialArrangement);document.querySelectorAll('[data-couple-step]').forEach(button=>button.onclick=async()=>{const pause=button.dataset.paused!=='true';await api(`/api/studio/bookings/${activeJourney.id}/workflow-control`,{method:'PUT',body:JSON.stringify({step_id:button.dataset.coupleStep,paused:pause})});await openJourneyV54(activeJourney.id);toast(pause?'This step is paused for this couple.':'This couple now follows the step again.')})}
function wireQuoteAddonModes(){document.querySelectorAll('[data-quote-addon-card]').forEach(card=>{const offered=card.querySelector('.quote-addon');card.querySelectorAll('input[type="radio"]').forEach(mode=>mode.onchange=()=>{if(mode.value==='mandatory'&&mode.checked)offered.checked=true;card.classList.toggle('is-required',card.querySelector('input[value="mandatory"]')?.checked===true)});offered.onchange=()=>{if(!offered.checked){const optional=card.querySelector('input[value="optional"]');if(optional)optional.checked=true;card.classList.remove('is-required')}}})}
function wireQuoteCustomRows(){document.querySelectorAll('.remove-custom-quote').forEach(button=>button.onclick=()=>button.closest('.quote-custom-row').remove())}
function wireJourneyTab(){if(['journey','payments'].includes(activeJourneyTab))wireClientJourneyControls();$('#add-note')?.addEventListener('click',openAddNote);$('#add-task')?.addEventListener('click',openAddTask);document.querySelectorAll('[data-delete-note]').forEach(button=>button.onclick=()=>deleteNote(button.dataset.deleteNote));document.querySelectorAll('[data-toggle-task]').forEach(button=>button.onclick=()=>toggleTask(button.dataset.toggleTask,button.dataset.taskStatus));document.querySelectorAll('[data-delete-task]').forEach(button=>button.onclick=()=>deleteTask(button.dataset.deleteTask));$('#compose-booking-email')?.addEventListener('click',()=>openComposeEmail(activeJourney));document.querySelectorAll('.reply-email').forEach(button=>button.onclick=()=>openReplyEmail(button.dataset.message));document.querySelectorAll('[data-email-message]').forEach(card=>card.onclick=async event=>{if(event.target.closest('a,button'))return;await api(`/api/studio/emails/${card.dataset.emailMessage}/read`,{method:'POST'});card.classList.remove('unread');await updateUnreadCount()});$('#upload-document')?.addEventListener('click',openUploadDocument);document.querySelectorAll('[data-delete-document]').forEach(button=>button.onclick=()=>deleteDocument(button.dataset.deleteDocument))}

function openEditBooking(){const j=activeJourney,c=j.client||{};openWorkDialog('Edit wedding details','COUPLE & WEDDING',`<div class="form-grid"><label class="wide-field">Display name<input id="edit-title" value="${escapeAttr(j.title)}" required></label><label>First name<input id="edit-first" value="${escapeAttr(c.first_name||'')}" required></label><label>Last name<input id="edit-last" value="${escapeAttr(c.last_name||'')}"></label><label>Partner name<input id="edit-partner" value="${escapeAttr(c.partner_name||'')}"></label><label>Email<input id="edit-email" type="email" value="${escapeAttr(c.email||'')}" required></label><label>Telephone<input id="edit-phone" value="${escapeAttr(c.phone||'')}"></label><label>Wedding date <small>Use Move date for a safe reschedule</small><input id="edit-date" type="date" value="${j.event_date||''}" disabled></label><label>Venue<input id="edit-venue" value="${escapeAttr(j.venue||'')}"></label></div>`,async dialog=>{activeJourney=await api(`/api/studio/bookings/${j.id}`,{method:'PATCH',body:JSON.stringify({title:dialog.querySelector('#edit-title').value,first_name:dialog.querySelector('#edit-first').value,last_name:dialog.querySelector('#edit-last').value,partner_name:dialog.querySelector('#edit-partner').value,email:dialog.querySelector('#edit-email').value,phone:dialog.querySelector('#edit-phone').value,event_date:j.event_date,venue:dialog.querySelector('#edit-venue').value})});await openJourneyV54(j.id);toast('Wedding details updated.')})}
function openMoveBooking(){const j=activeJourney;openWorkDialog('Move this wedding','SAFE DATE CHANGE',`<div class="form-grid"><label>New wedding date<input id="move-date" type="date" value="${j.event_date||''}" required></label><label class="wide-field">Reason for the record<input id="move-reason" required minlength="3" placeholder="The couple changed venue availability"></label><label class="check wide-field"><input id="move-money" type="checkbox" checked> Move the balance and invoice due dates by the same number of days</label></div><div class="safety-note small"><span>✓</span><div><strong>The new date is checked first</strong><p>Studio checks existing weddings and blocked dates, then updates future wedding-date reminders and Google Calendar.</p></div></div>`,async dialog=>{await api(`/api/studio/bookings/${j.id}/reschedule`,{method:'POST',body:JSON.stringify({event_date:dialog.querySelector('#move-date').value,reason:dialog.querySelector('#move-reason').value,move_financial_dates:dialog.querySelector('#move-money').checked})});await openJourneyV54(j.id);toast('Wedding moved and connected dates updated.')},'Move wedding')}
function cancelWedding(){openWorkDialog('Cancel this booking','PERMANENT RECORD',`<div class="form-grid"><label class="wide-field">Reason for cancellation<textarea id="cancel-reason" rows="5" required minlength="3" placeholder="Add a clear note for the permanent history"></textarea></label></div><div class="safety-note small warning-note"><span>!</span><div><strong>Future workflow items will stop</strong><p>The booking history, documents and financial record remain safely available.</p></div></div>`,async modal=>{await api(`/api/studio/bookings/${activeJourney.id}/cancel`,{method:'POST',body:JSON.stringify({reason:modal.querySelector('#cancel-reason').value})});await openJourneyV54(activeJourney.id);toast('Booking cancelled and future workflow items stopped.')},'Cancel booking')}
function setSpecialArrangement(){openWorkDialog('Record a payment arrangement','PRIVATE FINANCIAL NOTE',`<div class="form-grid"><label class="wide-field">What has been agreed?<textarea id="arrangement-note" rows="5" required minlength="3" placeholder="For example, balance will be paid in two instalments"></textarea></label></div><div class="safety-note small"><span>✓</span><div><strong>The wedding date stays secured</strong><p>This private note is kept with the booking so the agreed arrangement is clear.</p></div></div>`,async modal=>{await api(`/api/studio/bookings/${activeJourney.id}/payment-arrangement`,{method:'PUT',body:JSON.stringify({enabled:true,note:modal.querySelector('#arrangement-note').value})});await openJourneyV54(activeJourney.id);toast('Special arrangement recorded and the date secured.')},'Record arrangement')}
function openAddNote(){openWorkDialog('Add a private note','ONLY YOUR STUDIO SEES THIS',`<label>Note<textarea id="note-body" rows="6" required placeholder="Something useful to remember…"></textarea></label>`,async dialog=>{await api(`/api/studio/bookings/${activeJourney.id}/notes`,{method:'POST',body:JSON.stringify({body:dialog.querySelector('#note-body').value})});await openJourneyV54(activeJourney.id);toast('Private note added.')},'Add note')}
async function deleteNote(id){if(!confirm('Remove this private note?'))return;await api(`/api/studio/bookings/${activeJourney.id}/notes/${id}`,{method:'DELETE'});await openJourneyV54(activeJourney.id)}
function openAddTask(){openWorkDialog('Add a task','PRIVATE REMINDER',`<div class="form-grid"><label class="wide-field">What needs doing?<input id="task-title" required></label><label>Due date<input id="task-date" type="date"></label><label class="wide-field">Private notes<textarea id="task-notes" rows="4"></textarea></label></div>`,async dialog=>{await api(`/api/studio/tasks?booking_id=${activeJourney.id}`,{method:'POST',body:JSON.stringify({title:dialog.querySelector('#task-title').value,due_date:dialog.querySelector('#task-date').value||null,notes:dialog.querySelector('#task-notes').value})});await openJourneyV54(activeJourney.id);toast('Task added.')},'Add task')}
async function toggleTask(id,status){await api(`/api/studio/tasks/${id}`,{method:'PATCH',body:JSON.stringify({status:status==='completed'?'open':'completed'})});await openJourneyV54(activeJourney.id)}
async function deleteTask(id){if(!confirm('Remove this task?'))return;await api(`/api/studio/tasks/${id}`,{method:'DELETE'});await openJourneyV54(activeJourney.id)}
function openUploadDocument(){openWorkDialog('Upload a document','WEDDING FILES',`<div class="form-grid"><label class="wide-field">Choose file<input id="document-file" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.txt,.doc,.docx,.xls,.xlsx" required></label><label class="wide-field">Description<input id="document-description" maxlength="500" placeholder="Optional note about this file"></label></div><p class="helper">PDF, image, Word or Excel · maximum 20 MB.</p>`,async dialog=>{const form=new FormData();form.append('file',dialog.querySelector('#document-file').files[0]);form.append('description',dialog.querySelector('#document-description').value);await apiUpload(`/api/studio/bookings/${activeJourney.id}/documents`,form);await openJourneyV54(activeJourney.id);toast('Document uploaded securely.')},'Upload securely')}
async function deleteDocument(id){if(!confirm('Remove this document from the wedding?'))return;await api(`/api/studio/documents/${id}`,{method:'DELETE'});await openJourneyV54(activeJourney.id)}

function addressFromSender(value=''){const match=value.match(/<([^>]+)>/);return (match?match[1]:value).trim()}
function templateOptions(selected=''){return `<option value="">Start with a blank email</option>${emailTemplates.filter(row=>row.is_active).map(row=>`<option value="${row.id}" ${row.id===selected?'selected':''}>${escapeHtml(row.name)}</option>`).join('')}`}
async function openComposeEmail(j=null,reply=null){if(!emailTemplates.length){try{emailTemplates=await api('/api/studio/email-templates')}catch(error){toast(error.message,true)}}const recipient=reply?addressFromSender(reply.sender):j.client.email;const subject=reply?(/^re:/i.test(reply.subject)?reply.subject:`Re: ${reply.subject}`):'';const body=`<div class="form-grid"><label class="wide-field">Use a template<select id="compose-template">${templateOptions()}</select></label><label class="wide-field">To<input id="compose-recipient" type="email" value="${escapeAttr(recipient)}" required></label><label class="wide-field">Subject<input id="compose-subject" value="${escapeAttr(subject)}" required></label><label class="wide-field">Message<textarea id="compose-body" rows="10" required></textarea></label></div><p class="helper">Your saved signature and selected logo or award badge are added automatically.</p>`;const dialog=openWorkDialog(reply?'Reply to email':'Write a personal email','SEND FROM YOUR CONNECTED MAILBOX',body,async modal=>{const payload={recipient:modal.querySelector('#compose-recipient').value,subject:modal.querySelector('#compose-subject').value,body:modal.querySelector('#compose-body').value,template_id:modal.querySelector('#compose-template').value||null};if(reply)await api(`/api/studio/emails/${reply.id}/reply`,{method:'POST',body:JSON.stringify(payload)});else await api(`/api/studio/bookings/${j.id}/emails/send`,{method:'POST',body:JSON.stringify(payload)});if(j)await openJourneyV54(j.id,'emails');else{communicationsTab='inbox';await loadCommunications()}await updateUnreadCount();toast(reply?'Reply sent and recorded.':'Email sent and recorded.')});dialog.querySelector('button[type="submit"]').textContent=reply?'Send reply':'Send email';dialog.querySelector('#compose-template').onchange=event=>{const template=emailTemplates.find(row=>row.id===event.target.value);if(!template)return;dialog.querySelector('#compose-subject').value=template.subject;dialog.querySelector('#compose-body').value=template.body}}
async function openReplyEmail(id){const row=activeJourney.emails.find(item=>item.id===id);if(row)await openComposeEmail(activeJourney,row)}

async function loadCommunications(){try{[emailMessages,emailTemplates,emailBranding,workflowActions,weddings]=await Promise.all([api('/api/studio/emails'),api('/api/studio/email-templates'),api('/api/studio/email-branding'),api('/api/studio/workflow-actions'),api('/api/studio/bookings')]);renderCommunications();await updateUnreadCount()}catch(error){$('#communications-content').innerHTML=empty('Communications could not be loaded',error.message)}}
async function loadBrandAssetsV56(){try{emailBranding=await api('/api/studio/email-branding');const panel=$('#brand-logo-panel'),exists=emailBranding.has_logo;panel.innerHTML=`<header><div><span class="eyebrow">BUSINESS LOGO</span><h2>Use your logo in client communication</h2><p>Upload it once here. Quote emails, signed-contract confirmations and other Studio emails can use the same image.</p></div></header><div class="brand-logo-body"><div class="brand-logo-preview">${exists?`<img src="${emailBranding.logo_url}?v=${Date.now()}" alt="Business logo">`:'<span>YOUR LOGO</span>'}</div><div><strong>${exists?'Logo ready to use':'Add your studio logo'}</strong><p>PNG, JPG or WebP · maximum 3 MB. The image is embedded into email for reliable display.</p><label class="button primary">${exists?'Replace logo':'Upload logo'}<input id="brand-logo-upload" type="file" accept=".png,.jpg,.jpeg,.webp" hidden></label>${exists?'<button id="brand-logo-remove" class="button quiet" type="button">Remove logo</button>':''}</div></div>`;$('#brand-logo-upload').onchange=async event=>{const file=event.target.files[0];if(!file)return;const form=new FormData();form.append('file',file);try{await apiUpload('/api/studio/email-branding/assets/logo',form);await loadBrandAssetsV56();toast('Business logo uploaded and ready for emails.')}catch(error){toast(error.message,true)}};$('#brand-logo-remove')?.addEventListener('click',async()=>{if(!confirm('Remove this logo from future emails?'))return;await api('/api/studio/email-branding/assets/logo',{method:'DELETE'});await loadBrandAssetsV56();toast('Business logo removed.')})}catch(error){$('#brand-logo-panel').innerHTML=empty('Logo could not be loaded',error.message)}}
function renderCommunications(){document.querySelectorAll('[data-comms-tab]').forEach(button=>button.classList.toggle('active',button.dataset.commsTab===communicationsTab));const content=$('#communications-content');if(communicationsTab==='inbox')content.innerHTML=communicationsInbox();if(communicationsTab==='review')content.innerHTML=communicationsReview();if(communicationsTab==='templates')content.innerHTML=communicationsTemplates();if(communicationsTab==='signature')content.innerHTML=communicationsSignature();wireCommunications()}
function bookingName(id){return weddings.find(row=>row.id===id)?.title||'Unmatched email'}
function communicationsInbox(){return `<div class="communications-layout"><aside class="panel comms-summary"><span class="eyebrow">INBOX</span><strong>${emailMessages.filter(row=>row.direction==='inbound'&&!row.is_read).length}</strong><h3>unread message${emailMessages.filter(row=>row.direction==='inbound'&&!row.is_read).length===1?'':'s'}</h3><p>Refresh securely from the connected IMAP mailbox. Replies from known couples are attached to their wedding automatically.</p><button id="open-mail-settings" class="text-action">Email connection settings</button></aside><article class="panel comms-list">${emailMessages.length?emailMessages.map(row=>`<button data-open-email="${row.id}" class="${row.is_read?'':'unread'}"><span class="comms-direction">${row.direction==='inbound'?'↙':'↗'}</span><div><strong>${escapeHtml(row.subject||'(No subject)')}</strong><p>${escapeHtml(bookingName(row.booking_id))} · ${escapeHtml(row.direction==='inbound'?row.sender:row.recipient)}</p></div><em>${relativeTime(row.sent_at)}</em></button>`).join(''):empty('No messages yet','Refresh the inbox after connecting IMAP, or send a personal email from a couple’s wedding.')}</article></div>`}
function communicationsReview(){const open=workflowActions.filter(row=>!row.completed_at&&(['review','error','pending'].includes(row.status)||(row.status==='paused'&&['review','task'].includes(row.mode))));return `<div class="review-intro safety-note"><span>✓</span><div><strong>You approve what leaves the Studio</strong><p>Review-first emails can be edited, approved or skipped here. A global safety pause still prevents delivery during proofing.</p></div></div><div class="review-grid">${open.length?open.map(row=>`<article class="panel review-card ${row.status}"><header><div><span class="eyebrow">${escapeHtml(prettyAction(row.status))}</span><h3>${escapeHtml(row.payload.name||row.payload.task_title||prettyAction(row.trigger))}</h3></div><em>${relativeTime(row.due_at)}</em></header><p><strong>${escapeHtml(bookingName(row.booking_id))}</strong></p>${row.payload.subject?`<h4>${escapeHtml(row.payload.subject)}</h4>`:''}${row.payload.message_body?`<blockquote>${escapeHtml(row.payload.message_body)}</blockquote>`:''}${row.payload.last_error?`<p class="review-error">${escapeHtml(row.payload.last_error)}</p>`:''}<footer>${row.mode==='task'?`<button data-complete-action="${row.id}" class="button primary">Mark complete</button>`:`<button data-edit-action="${row.id}" class="button quiet">Edit</button>${row.status==='error'?`<button data-retry-action="${row.id}" class="button primary">Retry safely</button>`:`<button data-approve-action="${row.id}" class="button primary">Approve</button>`}`}<button data-skip-action="${row.id}" class="text-action">Skip</button></footer></article>`).join(''):empty('Review queue clear','There are no prepared messages or private tasks waiting for you.')}</div>`}
function communicationsTemplates(){return `<article class="panel workspace-card"><header><div><span class="eyebrow">EMAIL TEMPLATES</span><h2>Your words, ready when you need them</h2><p>Start with the included examples, then edit every subject and message into your own voice. Templates never send by themselves.</p></div><button id="new-email-template" class="button primary">＋ New template</button></header><div class="template-list">${emailTemplates.length?emailTemplates.map(row=>`<button data-edit-template="${row.id}"><span>${escapeHtml(row.category)}</span><strong>${escapeHtml(row.name)}</strong><small>${escapeHtml(row.subject||'No subject saved')}</small><em>${row.is_active?'Ready':'Hidden'}</em></button>`).join(''):empty('No templates yet','Save common replies, information and thank-you messages here.')}</div></article>`}
function communicationsSignature(){const b=emailBranding;return `<div class="signature-grid-v54"><form id="signature-form" class="panel workspace-card"><header><div><span class="eyebrow">EMAIL SIGNATURE</span><h2>A consistent, professional finish</h2><p>This is added to personal and workflow emails sent through Studio.</p></div></header><div class="form-grid"><label class="wide-field">Sign-off<textarea id="signature-signoff" rows="3">${escapeHtml(b.signoff||'')}</textarea></label><label>Name<input id="signature-name" value="${escapeAttr(b.signature_name||'')}"></label><label>Role or tagline<input id="signature-role" value="${escapeAttr(b.signature_role||'')}"></label><label>Telephone<input id="signature-phone" value="${escapeAttr(b.telephone||'')}"></label><label>Website<input id="signature-website" type="url" value="${escapeAttr(b.website||'')}" placeholder="https://..."></label><label class="check"><input id="signature-show-logo" type="checkbox" ${b.show_logo?'checked':''}> Show logo</label><label class="check"><input id="signature-show-badge" type="checkbox" ${b.show_badge?'checked':''}> Show award badge</label><label class="check wide-field"><input id="owner-notifications" type="checkbox" ${b.owner_notifications_enabled?'checked':''}> Email me when a couple accepts, signs or submits a form</label></div><button class="button primary" type="submit">Save signature</button></form><aside class="panel signature-assets"><span class="eyebrow">BRAND IMAGES</span><h2>Logo and awards</h2>${signatureAsset('logo',b.has_logo,b.logo_url)}${signatureAsset('badge',b.has_badge,b.badge_url)}<p class="record-note">PNG, JPG or WebP · maximum 3 MB. Images are embedded in outgoing email so they display more reliably.</p></aside></div>`}
function signatureAsset(kind,exists,url){const label=kind==='logo'?'Business logo':'Award badge',preview=exists?`<img src="${url}?v=${Date.now()}" alt="${label}">`:`<span class="asset-placeholder">${kind==='logo'?'LOGO':'AWARD'}</span>`;return `<article><div>${preview}</div><section><strong>${label}</strong><label class="button quiet">${exists?'Replace':'Upload'}<input data-brand-asset="${kind}" type="file" accept=".png,.jpg,.jpeg,.webp" hidden></label>${exists?`<button data-delete-asset="${kind}" class="text-action">Remove</button>`:''}</section></article>`}
function wireCommunications(){document.querySelectorAll('[data-comms-tab]').forEach(button=>button.onclick=()=>{communicationsTab=button.dataset.commsTab;renderCommunications()});$('#open-mail-settings')?.addEventListener('click',()=>showSection('mailbox'));document.querySelectorAll('[data-open-email]').forEach(button=>button.onclick=()=>openCommunicationMessage(button.dataset.openEmail));document.querySelectorAll('[data-edit-action]').forEach(button=>button.onclick=()=>openActionReview(button.dataset.editAction));document.querySelectorAll('[data-approve-action]').forEach(button=>button.onclick=()=>actOnWorkflow(button.dataset.approveAction,'approve'));document.querySelectorAll('[data-retry-action]').forEach(button=>button.onclick=()=>actOnWorkflow(button.dataset.retryAction,'retry'));document.querySelectorAll('[data-complete-action]').forEach(button=>button.onclick=()=>actOnWorkflow(button.dataset.completeAction,'complete'));document.querySelectorAll('[data-skip-action]').forEach(button=>button.onclick=()=>actOnWorkflow(button.dataset.skipAction,'skip'));$('#new-email-template')?.addEventListener('click',()=>openEmailTemplate());document.querySelectorAll('[data-edit-template]').forEach(button=>button.onclick=()=>openEmailTemplate(emailTemplates.find(row=>row.id===button.dataset.editTemplate)));$('#signature-form')?.addEventListener('submit',saveSignature);document.querySelectorAll('[data-brand-asset]').forEach(input=>input.onchange=()=>uploadBrandAsset(input.dataset.brandAsset,input.files[0]));document.querySelectorAll('[data-delete-asset]').forEach(button=>button.onclick=()=>deleteBrandAsset(button.dataset.deleteAsset))}
async function openCommunicationMessage(id){const row=emailMessages.find(item=>item.id===id);if(!row)return;if(!row.is_read){await api(`/api/studio/emails/${row.id}/read`,{method:'POST'});row.is_read=true;updateUnreadCount()}const matched=row.booking_id?bookingName(row.booking_id):'Not yet matched to a wedding';const body=`<article class="opened-message"><p><strong>${row.direction==='inbound'?'From':'To'}:</strong> ${escapeHtml(row.direction==='inbound'?row.sender:row.recipient)}</p><p><strong>Wedding:</strong> ${escapeHtml(matched)}</p><div>${escapeHtml(row.body_text||'').replaceAll('\n','<br>')}</div>${row.attachments?.length?`<footer>${row.attachments.map((item,index)=>`<a href="/api/studio/emails/${row.id}/attachments/${index}">📎 ${escapeHtml(item.name)}</a>`).join('')}</footer>`:''}</article>`;const dialog=openWorkDialog(row.subject||'(No subject)','EMAIL',body,async()=>{}),submit=dialog.querySelector('button[type="submit"]');if(row.direction!=='inbound'){submit.remove();return}submit.textContent='Reply';dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();submit.disabled=true;try{let booking=null;if(row.booking_id){booking=await api(`/api/studio/bookings/${row.booking_id}/journey`);activeJourney=booking}dialog.close();await openComposeEmail(booking,row)}catch(error){dialog.querySelector('#work-error').textContent=error.message;submit.disabled=false}}}
function openActionReview(id){const row=workflowActions.find(item=>item.id===id);openWorkDialog('Review this message','NOT SENT YET',`<div class="form-grid"><label class="wide-field">Subject<input id="review-subject" value="${escapeAttr(row.payload.subject||'')}"></label><label class="wide-field">Message<textarea id="review-message" rows="10">${escapeHtml(row.payload.message_body||'')}</textarea></label></div>`,async dialog=>{await api(`/api/studio/workflow-actions/${id}/review`,{method:'PUT',body:JSON.stringify({subject:dialog.querySelector('#review-subject').value,message_body:dialog.querySelector('#review-message').value})});await loadCommunications();toast('Prepared message updated. It is still waiting for approval.')})}
async function actOnWorkflow(id,action){if(action==='skip'&&!confirm('Skip this workflow item? It will not contact the couple.'))return;try{await api(`/api/studio/workflow-actions/${id}/${action}`,{method:'POST'});await loadCommunications();const messages={approve:'Approved. The global safety pause still applies.',retry:'Queued safely for another attempt.',complete:'Private task completed.',skip:'Workflow item skipped.'};toast(messages[action])}catch(error){toast(error.message,true)}}
function openEmailTemplate(row=null){const dialog=openWorkDialog(row?'Edit email template':'New email template','PERSONAL EMAIL SHORTCUT',`<div class="form-grid"><label>Name<input id="template-name" value="${escapeAttr(row?.name||'')}" required></label><label>Category<input id="template-category" value="${escapeAttr(row?.category||'General')}" required></label><label class="wide-field">Subject<input id="template-subject" value="${escapeAttr(row?.subject||'')}"></label><label class="wide-field">Message<textarea id="template-body" rows="10" required>${escapeHtml(row?.body||'')}</textarea><small>Personalise with {{couple_first_name}}, {{couple_names}}, {{wedding_date}}, {{venue}}, {{business_name}}, {{client_portal_link}} and {{final_timings_link}}. Final Timings links can be used in the 30-day or 60-day scheduled email.</small></label><label class="check wide-field"><input id="template-active" type="checkbox" ${row?.is_active===false?'':'checked'}> Available when writing an email</label></div>${row?'<button id="delete-email-template" type="button" class="button danger">Delete template</button>':''}`,async modal=>{const payload={name:modal.querySelector('#template-name').value,category:modal.querySelector('#template-category').value,subject:modal.querySelector('#template-subject').value,body:modal.querySelector('#template-body').value,is_active:modal.querySelector('#template-active').checked};await api(`/api/studio/email-templates${row?'/'+row.id:''}`,{method:row?'PUT':'POST',body:JSON.stringify(payload)});await loadCommunications();toast(row?'Template updated.':'Template saved.')});dialog.querySelector('#delete-email-template')?.addEventListener('click',async()=>{if(!confirm('Delete this email template? Previously sent emails stay unchanged.'))return;await api(`/api/studio/email-templates/${row.id}`,{method:'DELETE'});dialog.close();await loadCommunications();toast('Template deleted.')})}
async function saveSignature(event){event.preventDefault();try{emailBranding=await api('/api/studio/email-branding',{method:'PUT',body:JSON.stringify({signoff:$('#signature-signoff').value,signature_name:$('#signature-name').value,signature_role:$('#signature-role').value,telephone:$('#signature-phone').value,website:$('#signature-website').value,show_logo:$('#signature-show-logo').checked,show_badge:$('#signature-show-badge').checked,owner_notifications_enabled:$('#owner-notifications').checked})});renderCommunications();toast('Email signature saved.')}catch(error){toast(error.message,true)}}
async function uploadBrandAsset(kind,file){if(!file)return;try{const form=new FormData();form.append('file',file);emailBranding=await apiUpload(`/api/studio/email-branding/assets/${kind}`,form);renderCommunications();toast(`${kind==='logo'?'Logo':'Award badge'} uploaded.`)}catch(error){toast(error.message,true)}}
async function deleteBrandAsset(kind){if(!confirm(`Remove this ${kind==='logo'?'logo':'award badge'} from future emails?`))return;await api(`/api/studio/email-branding/assets/${kind}`,{method:'DELETE'});emailBranding=await api('/api/studio/email-branding');renderCommunications()}
$('#refresh-inbox').onclick=async()=>{const button=$('#refresh-inbox');button.disabled=true;button.textContent='Refreshing…';try{const result=await api('/api/studio/mailbox/sync',{method:'POST'});await loadCommunications();toast(result.imported?`${result.imported} new message${result.imported===1?'':'s'} added.`:'Inbox is already up to date.')}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent='Refresh inbox'}};

function isWeddingDateEmail(step){return step?.action_type==='email'&&step.trigger_event==='wedding_date'&&step.timing_direction==='before'&&step.offset_unit==='days'}
function isFinalTimingsEmail(step){return !!step&&(step.message_body||'').includes('{{final_timings_link}}')}
async function openScheduledEmail(step=null){
  if(!emailTemplates.length){try{emailTemplates=await api('/api/studio/email-templates')}catch(error){toast(error.message,true)}}
  const allowedDays=[120,90,60,30],days=allowedDays.includes(Number(step?.offset_value))?Number(step.offset_value):90;
  const checkIn=emailTemplates.find(row=>row.name==='Wedding planning check-in'),initialSubject=step?.subject||checkIn?.subject||'A little check-in before your wedding',initialBody=step?.message_body||checkIn?.body||'Hi {{couple_first_name}},\n\nI just wanted to check in and say hello as your wedding gets closer. I am still here, everything is safely in the diary, and I hope all the planning is going well.\n\nIf there is anything you would like to ask or update me about, simply reply to this email.';
  const body=`<div class="form-grid scheduled-email-editor"><label class="wide-field">Email name <small>Only you see this name</small><input id="scheduled-email-name" value="${escapeAttr(step?.name||`Wedding check-in - ${days} days`)}" required></label><label>Send before the wedding<select id="scheduled-email-days">${allowedDays.map(value=>`<option value="${value}" ${value===days?'selected':''}>${value} days before</option>`).join('')}</select></label><label>Start from a saved template<select id="scheduled-email-template">${templateOptions()}</select></label><label class="wide-field scheduled-final-option"><input id="scheduled-email-final" type="checkbox" ${isFinalTimingsEmail(step)?'checked':''}><span><strong>Include the Final Timings form</strong><small>Available for the 30-day or 60-day email. The form stays hidden until this email is actually sent.</small></span></label><label class="wide-field">Subject<input id="scheduled-email-subject" value="${escapeAttr(initialSubject)}" required></label><label class="wide-field">Message<textarea id="scheduled-email-body" rows="10" required>${escapeHtml(initialBody)}</textarea><small>Use {{couple_first_name}}, {{wedding_date}}, {{venue}} and {{business_name}} to personalise it.</small></label><label class="check"><input id="scheduled-email-enabled" type="checkbox" ${step?.mode==='off'?'':'checked'}> Enable this email</label><label class="check"><input id="scheduled-email-auto" type="checkbox" ${step?.mode==='automatic'?'checked':''}> Send automatically at the chosen time</label></div><div class="safety-note small"><span>✓</span><div><strong>You can create more than one</strong><p>Add separate emails at 120, 90, 60 and 30 days. Leave automatic unticked if you want each one waiting in the Review queue first.</p></div></div>`;
  const dialog=openWorkDialog(step?'Manage scheduled email':'New scheduled email','WEDDING-DATE EMAIL',body,async modal=>{
    const chosenDays=Number(modal.querySelector('#scheduled-email-days').value),finalTimings=[30,60].includes(chosenDays)&&modal.querySelector('#scheduled-email-final').checked;
    let message=modal.querySelector('#scheduled-email-body').value.trim();
    if(finalTimings&&!message.includes('{{final_timings_link}}'))message+=`\n\n{{final_timings_link}}`;
    if(!finalTimings)message=message.replaceAll('{{final_timings_link}}','').replace(/\n{3,}/g,'\n\n').trim();
    const payload={name:modal.querySelector('#scheduled-email-name').value.trim(),trigger_event:'wedding_date',timing_direction:'before',offset_value:chosenDays,offset_unit:'days',action_type:'email',subject:modal.querySelector('#scheduled-email-subject').value.trim(),message_body:message,task_title:'',is_paused:false,sort_order:step?.sort_order??workflows.find(row=>row.id===activeWorkflowId).steps.length};
    const saved=await api(`/api/studio/workflows/${activeWorkflowId}/steps${step?'/'+step.id:''}`,{method:step?'PATCH':'POST',body:JSON.stringify(payload)});
    const enabled=modal.querySelector('#scheduled-email-enabled').checked,automatic=modal.querySelector('#scheduled-email-auto').checked,mode=enabled?(automatic?'automatic':'review'):'off';
    await api(`/api/studio/workflow-steps/${saved.id}/mode`,{method:'PUT',body:JSON.stringify({mode,apply_to_existing:false})});
    await loadWorkflowV54();toast(step?'Scheduled email updated.':'Scheduled email added. You can add another at a different interval.');
  },step?'Save email':'Add scheduled email');
  const daysSelect=dialog.querySelector('#scheduled-email-days'),finalCheck=dialog.querySelector('#scheduled-email-final'),autoCheck=dialog.querySelector('#scheduled-email-auto'),enabledCheck=dialog.querySelector('#scheduled-email-enabled');
  const syncFinalOption=()=>{const available=[30,60].includes(Number(daysSelect.value));finalCheck.disabled=!available;if(!available)finalCheck.checked=false;finalCheck.closest('label').classList.toggle('unavailable',!available)};
  daysSelect.onchange=()=>{syncFinalOption();if(!step)dialog.querySelector('#scheduled-email-name').value=`Wedding check-in - ${daysSelect.value} days`};syncFinalOption();
  enabledCheck.onchange=()=>{autoCheck.disabled=!enabledCheck.checked;if(!enabledCheck.checked)autoCheck.checked=false};enabledCheck.onchange();
  dialog.querySelector('#scheduled-email-template').onchange=event=>{const template=emailTemplates.find(row=>row.id===event.target.value);if(!template)return;dialog.querySelector('#scheduled-email-subject').value=template.subject;dialog.querySelector('#scheduled-email-body').value=template.body;const finalTemplate=template.name==='Final timings request'||template.category==='Final timings'||template.body.includes('{{final_timings_link}}');if(finalTemplate){daysSelect.value='30';finalCheck.checked=true;syncFinalOption();dialog.querySelector('#scheduled-email-name').value='Send final timings form'}};
}

async function loadWorkflowV54(){try{workflows=await api('/api/studio/workflows');if(!workflows.length){await api('/api/studio/workflows',{method:'POST',body:JSON.stringify({name:'Main client journey',description:'Your enquiry-to-wedding workflow.',is_active:false,sort_order:0})});workflows=await api('/api/studio/workflows')}if(!activeWorkflowId||!workflows.some(row=>row.id===activeWorkflowId))activeWorkflowId=workflows[0].id;const index=workflows.findIndex(row=>row.id===activeWorkflowId);if(index>0)[workflows[0],workflows[index]]=[workflows[index],workflows[0]];const w=workflows[0];const header=$('.workflow-panel>header');header.innerHTML=`<div><span class="eyebrow">WORKFLOW</span><h2 id="workflow-name">${escapeHtml(w.name)}</h2><p>${escapeHtml(w.description||'')}</p></div><div class="workflow-header-actions"><select id="workflow-picker">${workflows.map(row=>`<option value="${row.id}" ${row.id===w.id?'selected':''}>${escapeHtml(row.name)}</option>`).join('')}</select><span id="workflow-revision" class="revision">Revision ${w.revision} · ${w.is_active?'Active for new events':'Paused'}</span><button id="workflow-more" class="button quiet">Manage</button></div>`;$('#workflow-steps').innerHTML=w.steps.length?w.steps.map((s,i)=>`<button class="timeline-step" data-step-id="${s.id}"><span class="step-number">${i+1}</span><div><small>${escapeHtml(triggers[s.trigger_event]||prettyAction(s.trigger_event))}</small><strong>${escapeHtml(s.name)}</strong><p>${s.timing_direction==='immediately'?'Immediately':`${s.offset_value} ${s.offset_unit} ${s.timing_direction}`} · ${s.action_type==='email'?'Email to couple':'Manual task'}</p></div><em>${escapeHtml(modeNames[s.mode]||'Disabled')}</em></button>`).join(''):empty('Build your first step','Every new step begins disabled so it cannot surprise a couple.');document.querySelectorAll('[data-step-id]').forEach(button=>button.onclick=()=>openStep(w.steps.find(step=>step.id===button.dataset.stepId)));$('#workflow-picker').onchange=event=>{activeWorkflowId=event.target.value;loadWorkflowV54()};$('#workflow-more').onclick=()=>openWorkflowManager(w);if(!$('#new-workflow')){const newButton=document.createElement('button');newButton.id='new-workflow';newButton.className='button quiet';newButton.textContent='＋ New workflow';$('#new-step').before(newButton);newButton.onclick=openNewWorkflow}}catch(error){toast(error.message,true)}}
async function loadWorkflow(){return loadWorkflowV54()}
function openNewWorkflow(){openWorkDialog('Create another workflow','SAFE, PAUSED DRAFT',`<div class="form-grid"><label>Name<input id="new-workflow-name" required placeholder="Mini weddings"></label><label class="wide-field">Description<textarea id="new-workflow-description" rows="3"></textarea></label></div><div class="safety-note small"><span>Ⅱ</span><div><strong>It starts paused and empty</strong><p>Add and review every step before deliberately activating it for future events.</p></div></div>`,async dialog=>{const row=await api('/api/studio/workflows',{method:'POST',body:JSON.stringify({name:dialog.querySelector('#new-workflow-name').value,description:dialog.querySelector('#new-workflow-description').value,is_active:false,sort_order:workflows.length})});activeWorkflowId=row.id;await loadWorkflowV54();toast('New workflow created as a safe paused draft.')})}
function openWorkflowManager(w){const body=`<div class="workflow-manage"><p><strong>${escapeHtml(w.name)}</strong></p><p>${w.is_active?'This workflow applies to new matching events. Existing couples are not changed.':'This workflow is paused. Its client history remains available.'}</p><button id="toggle-workflow" type="button" class="button ${w.is_active?'quiet':'primary'}">${w.is_active?'Pause workflow':'Activate for new events'}</button><button id="duplicate-workflow" type="button" class="button quiet">Duplicate as paused copy</button>${!w.is_active?'<button id="delete-workflow" type="button" class="button danger">Delete unused workflow</button>':''}</div>`;const dialog=openWorkDialog('Manage workflow','WORKFLOW SETTINGS',body,async()=>{});dialog.querySelector('button[type="submit"]').remove();dialog.querySelector('#toggle-workflow').onclick=async()=>{if(!w.is_active&&!confirm('Activate this workflow for new matching events only? Existing couples will not be scheduled retroactively.'))return;await api(`/api/studio/workflows/${w.id}/${w.is_active?'pause':'activate'}`,{method:'POST'});dialog.close();await loadWorkflowV54();toast(w.is_active?'Workflow paused.':'Workflow active for new events only.')};dialog.querySelector('#duplicate-workflow').onclick=async()=>{const copy=await api(`/api/studio/workflows/${w.id}/duplicate`,{method:'POST'});activeWorkflowId=copy.id;dialog.close();await loadWorkflowV54();toast('Paused copy created. Nothing was scheduled.')};dialog.querySelector('#delete-workflow')?.addEventListener('click',async()=>{if(!confirm('Delete this unused workflow? A workflow with client history cannot be deleted.'))return;await api(`/api/studio/workflows/${w.id}`,{method:'DELETE'});activeWorkflowId=null;dialog.close();await loadWorkflowV54();toast('Unused workflow deleted.')})}

const loadWorkflowV54Base=loadWorkflowV54;
loadWorkflowV54=async function(){
  await loadWorkflowV54Base();
  const workflow=workflows.find(row=>row.id===activeWorkflowId)||workflows[0];
  document.querySelectorAll('[data-step-id]').forEach(button=>{const step=workflow.steps.find(row=>row.id===button.dataset.stepId);button.onclick=()=>isWeddingDateEmail(step)?openScheduledEmail(step):openStep(step);if(isFinalTimingsEmail(step)){const summary=button.querySelector('p');if(summary)summary.textContent=`${step.offset_value} days before · Email with Final Timings form`}});
  $('#new-workflow')?.remove();
  let newEmail=$('#new-scheduled-email');
  if(!newEmail){newEmail=document.createElement('button');newEmail.id='new-scheduled-email';newEmail.className='button quiet';newEmail.textContent='＋ New email';$('#new-step').before(newEmail)}
  newEmail.onclick=()=>openScheduledEmail();
}

